        }

        foreach (array_chunk($records, 100) as $chunk) {
            DB::table('lots')->upsert(
                $chunk,
                ['id'],
                [
                    'number',
                    'model_id',
                    'organizer_id',
                    'vendor_id',
                    'legacy_vendor_id',
                    'initial_quantity',
                    'current_quantity',
                    'entry_type',
                    'po_number',
                    'purchase_grant_date',
                    'memo_number',
                    'memo_url',
                    'burden',
                    'project_id',
                    'updated_at',
                ]
            );
        }

        if ($isSqlsrv) {
            DB::unprepared('SET IDENTITY_INSERT lots OFF;');
        }
    }
}
